function getCurrentLanguage(){return(window.location.pathname.split("/").pop()||"index.html").endsWith("-en.html")?"en":"fr"}async function loadBlogPosts(){const t=document.getElementById("blog-posts");if(t)try{const e=await fetch("./data/devlog.json");if(!e.ok)throw new Error("Failed to load devlog");const n=(await e.json()).posts||[],o=getCurrentLanguage();if(0===n.length)return void(t.innerHTML='<div class="no-posts">No posts yet. Check back soon!</div>');n.sort((t,e)=>new Date(e.date)-new Date(t.date));let s="";n.forEach(t=>{const e="en"===o?t.title_en:t.title_fr,n="en"===o?t.excerpt_en:t.excerpt_fr,a="en"===o?t.content_en:t.content_fr,r=formatDate(t.date,o),l=t.category||"update";s+=`\n        <article class="blog-post" data-post-id="${t.id}">\n          <div class="blog-post-date">${r}</div>\n          <h2 class="blog-post-title">${e}</h2>\n          <span class="blog-post-category">${l}</span>\n          <p class="blog-post-excerpt">${n}</p>\n          <div class="blog-post-content" style="display: none;">\n            ${a}\n          </div>\n          <a href="#" class="read-more" onclick="togglePostContent(event, '${t.id}')">\n            ${"en"===o?"Read more":"Lire plus"}\n          </a>\n        </article>\n      `}),t.innerHTML=s}catch(e){console.error("Error loading blog posts:",e),t.innerHTML='<div class="no-posts">Error loading blog posts.</div>'}}function formatDate(t,e="fr"){const n=new Date(t),o={year:"numeric",month:"long",day:"numeric"};return"en"===e?n.toLocaleDateString("en-US",o):n.toLocaleDateString("fr-FR",o)}function togglePostContent(t,e){t.preventDefault();const n=document.querySelector(`[data-post-id="${e}"]`),o=n.querySelector(".blog-post-content"),s=n.querySelector(".read-more"),a=getCurrentLanguage();"none"===o.style.display?(o.style.display="block",s.textContent="en"===a?"Show less":"Afficher moins"):(o.style.display="none",s.textContent="en"===a?"Read more":"Lire plus")}document.addEventListener("DOMContentLoaded",function(){loadBlogPosts()});